ALTER TABLE public.jobs ADD COLUMN city text, ADD COLUMN region text, ADD COLUMN skills text[] NOT NULL DEFAULT '{}', ADD COLUMN industry text, ADD COLUMN experience_min numeric, ADD COLUMN experience_max numeric, ADD COLUMN remote_eligibility text, ADD COLUMN last_application_checked_at timestamptz, ADD COLUMN verification_basis text, ADD COLUMN admin_hold boolean NOT NULL DEFAULT false, ADD COLUMN canonical_apply_url text;
CREATE TABLE public.job_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE, checked_at timestamptz NOT NULL DEFAULT now(), status text NOT NULL, http_status int, final_url text, evidence text NOT NULL);
GRANT ALL ON public.job_verifications TO service_role; ALTER TABLE public.job_verifications ENABLE ROW LEVEL SECURITY; CREATE INDEX job_verifications_job_idx ON public.job_verifications(job_id,checked_at DESC);
CREATE TABLE public.job_operational_summaries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), day date NOT NULL UNIQUE, live int NOT NULL DEFAULT 0, expired int NOT NULL DEFAULT 0, source_failures int NOT NULL DEFAULT 0, open_reports int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.job_operational_summaries TO service_role; ALTER TABLE public.job_operational_summaries ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.job_publication_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES public.jobs(id) ON DELETE CASCADE, event text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.job_publication_events TO service_role; ALTER TABLE public.job_publication_events ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.audit_job_publication() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' OR NEW.verification_status IS DISTINCT FROM OLD.verification_status OR NEW.application_status IS DISTINCT FROM OLD.application_status THEN INSERT INTO public.job_publication_events(job_id,event) VALUES(NEW.id,NEW.verification_status||'/'||NEW.application_status); END IF; RETURN NEW; END $$;
CREATE TRIGGER audit_job_publication AFTER INSERT OR UPDATE ON public.jobs FOR EACH ROW EXECUTE FUNCTION public.audit_job_publication();
ALTER POLICY "Public sees only fresh verified open jobs" ON public.jobs USING (verification_status='VERIFIED' AND application_status='OPEN' AND source_access_status='AUTHORIZED' AND is_primary AND NOT admin_hold AND original_posted_at<=now() AND original_posted_at>now()-interval '24 hours' AND expires_at>now() AND last_verified_at>now()-interval '3 hours' AND last_application_checked_at>now()-interval '30 minutes' AND verification_basis='authorized_feed_and_live_link');
CREATE FUNCTION public.jobs_expiry_maintenance() RETURNS int LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n int; BEGIN UPDATE public.jobs SET application_status='EXPIRED',updated_at=now() WHERE expires_at<=now() AND application_status='OPEN'; GET DIAGNOSTICS n=ROW_COUNT; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.jobs_expiry_maintenance() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.jobs_expiry_maintenance() TO service_role;
CREATE FUNCTION public.jobs_daily_summary() RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public AS $$ INSERT INTO public.job_operational_summaries(day,live,expired,source_failures,open_reports) SELECT current_date,(SELECT count(*) FROM public.jobs WHERE verification_status='VERIFIED' AND application_status='OPEN' AND NOT admin_hold AND is_primary AND original_posted_at>now()-interval '24 hours' AND original_posted_at<=now() AND expires_at>now() AND last_application_checked_at>now()-interval '30 minutes'),(SELECT count(*) FROM public.jobs WHERE expires_at>=current_date AND expires_at<current_date+interval '1 day'),(SELECT count(*) FROM public.job_sources WHERE last_error IS NOT NULL),(SELECT count(*) FROM public.reported_jobs WHERE status='open') ON CONFLICT(day) DO UPDATE SET live=excluded.live,expired=excluded.expired,source_failures=excluded.source_failures,open_reports=excluded.open_reports; $$;
REVOKE ALL ON FUNCTION public.jobs_daily_summary() FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.jobs_daily_summary() TO service_role;
CREATE INDEX jobs_skills_idx ON public.jobs USING gin(skills); CREATE INDEX jobs_application_check_idx ON public.jobs(last_application_checked_at);
